// Verify the RingCentral webhook delivery.
//
// Two modes we must handle:
//   1. Validation handshake — RC POSTs with a `Validation-Token` header
//      and an empty body. We must echo the token back within 5s or the
//      subscription is rejected.
//   2. Signed delivery — when the subscription was created with a
//      `verificationToken`, RC echoes it in `Verification-Token` on every push.
//      Compare constant-time against the env value.
//
// This mirrors `ringcentral_adapter.verify_webhook` in
// /Users/shubh/n8n-office/python/integrations/ringcentral_adapter.py.
// If you change the Python logic, change this in lockstep.

const headers = $input.first().json.headers || {};

function getHeader(name) {
  const target = name.toLowerCase();
  for (const k of Object.keys(headers)) {
    if (k.toLowerCase() === target) return headers[k];
  }
  return undefined;
}

// TODO: WIRE CREDS - RC_WEBHOOK_VERIFICATION_TOKEN
//   Set in n8n env (Settings → Variables) or the n8n process env. Must match
//   the token passed to ringcentral_adapter.subscribe_sms_webhook(...).
const expected = $env.RC_WEBHOOK_VERIFICATION_TOKEN || '';

const validationToken = getHeader('Validation-Token');
if (validationToken) {
  return [{
    json: {
      _verify: {
        ok: true,
        mode: 'validation',
        validation_token: validationToken,
        reason: 'handshake'
      },
      _payload: {},
      _from: '',
      _to: '',
      _text: ''
    }
  }];
}

const presented = getHeader('Verification-Token') || '';
let ok = true;
let reason = 'no expected token configured; delivery accepted unverified';
if (expected) {
  // Constant-time-ish comparison: same length + char-by-char XOR.
  if (presented.length !== expected.length) {
    ok = false;
    reason = 'verification token length mismatch';
  } else {
    let diff = 0;
    for (let i = 0; i < presented.length; i++) {
      diff |= presented.charCodeAt(i) ^ expected.charCodeAt(i);
    }
    if (diff !== 0) {
      ok = false;
      reason = 'verification token mismatched';
    } else {
      reason = 'verification token matched';
    }
  }
}

// Pull through the JSON body (n8n parses it for us when Content-Type is JSON).
const body = $input.first().json.body || {};

return [{
  json: {
    _verify: { ok, mode: 'delivery', validation_token: null, reason },
    _payload: body
  }
}];

// Extract (from_number, to_number, text, message_id) from either:
//   1. A direct test payload  ({ from, to, text })
//   2. The RC lightweight envelope  ({ body: { from, to, subject, id } })
//   3. The RC full envelope  ({ body: { changes: [ { newMessages: [...] } ] } })
// Mirrors `extract_sms_fields()` in triage-router.py — keep in lockstep.

const payload = $json._payload || {};
let from = '';
let to = '';
let text = '';
let messageId = '';

// Shape 1.
if (payload.from || payload.to || payload.text || payload.body) {
  from = String(payload.from || '');
  to = String(payload.to || '');
  text = String(payload.text || payload.body || '');
  messageId = String(payload.id || '');
}

// Shape 2/3 — nested under `body`.
const b = (payload.body && typeof payload.body === 'object') ? payload.body : null;
if (b) {
  if (b.subject && !text) text = String(b.subject);
  if (b.from && b.from.phoneNumber && !from) from = String(b.from.phoneNumber);
  if (Array.isArray(b.to) && b.to.length && !to) to = String(b.to[0].phoneNumber || '');
  if (b.id && !messageId) messageId = String(b.id);

  if (Array.isArray(b.changes)) {
    for (const ch of b.changes) {
      if (!ch || !Array.isArray(ch.newMessages) || !ch.newMessages.length) continue;
      const m = ch.newMessages[0] || {};
      if (!text && m.subject) text = String(m.subject);
      if (!from && m.from && m.from.phoneNumber) from = String(m.from.phoneNumber);
      if (!to && Array.isArray(m.to) && m.to.length) to = String(m.to[0].phoneNumber || '');
      if (!messageId && m.id) messageId = String(m.id);
      break;
    }
  }
}

return [{
  json: {
    _verify: $json._verify,
    _payload: payload,
    sms: {
      from_number: from,
      to_number: to,
      text,
      message_id: messageId
    }
  }
}];

