// Parse Claude's reply, coerce unknown labels to general_message, attach to
// the running item. Mirrors `_safe_parse_intent` + the dispatcher coercion
// guard in triage-router.py — keep in lockstep.

const VALID = ['appointment', 'file_request', 'patient_lookup', 'general_message'];
const FALLBACK = 'general_message';

const upstream = $input.first().json;

// HTTP Request node with neverError=true gives us either the parsed JSON body
// or, on error, the error envelope. Detect both.
let apiBody = upstream;
if (upstream && upstream.body && typeof upstream.body === 'object') {
  apiBody = upstream.body;
}

let classifierText = '';
if (apiBody && Array.isArray(apiBody.content)) {
  for (const block of apiBody.content) {
    if (block && block.type === 'text') { classifierText = block.text || ''; break; }
  }
}

function safeParse(text) {
  let raw = (text || '').trim();
  if (raw.startsWith('```')) {
    raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  }
  try {
    const obj = JSON.parse(raw);
    if (obj && typeof obj === 'object') return obj;
  } catch (_) { /* fall through */ }
  return { intent: FALLBACK, secondary: [], confidence: 'low', reason: 'classifier returned non-JSON' };
}

const parsed = safeParse(classifierText);
let intent = String(parsed.intent || '').toLowerCase();
if (!VALID.includes(intent)) {
  intent = FALLBACK;
}

const classification = {
  intent,
  secondary: Array.isArray(parsed.secondary) ? parsed.secondary : [],
  confidence: parsed.confidence || 'medium',
  reason: parsed.reason || ''
};

// Pull the SMS fields back through. We have to look them up via the upstream
// item rather than $json because the HTTP Request node replaced our payload
// with the API response. Use $items() on the Extract node.
const extracted = $items('Extract SMS fields', 0, 0)[0].json;

return [{
  json: {
    _verify: extracted._verify,
    sms: extracted.sms,
    classification,
    classifier_raw: classifierText
  }
}];

// Stub handler for `appointment`. Real implementation ships per Q2 (last —
// requires SIS write access + Q5 sign-off procedure). For now, queue for staff.
return [{ json: { handled: false, intent: 'appointment', note: 'queued for staff (handler not yet wired)', sms: $json.sms, classification: $json.classification, _verify: $json._verify } }];

// Stub handler for `file_request`. Real implementation ships per Q2 (second —
// Drive read + Q4 SMS approval gate). For now, queue for staff.
return [{ json: { handled: false, intent: 'file_request', note: 'queued for staff (handler not yet wired)', sms: $json.sms, classification: $json.classification, _verify: $json._verify } }];

// Stub handler for `patient_lookup`. Real implementation is in the sibling
// flow at /Users/shubh/n8n-office/python/flows/patient-lookup.py (Q2: ships
// first because it's the substrate every other flow needs). When that flow
// gets its own HTTP endpoint, replace this Function with an HTTP Request.
return [{ json: { handled: false, intent: 'patient_lookup', note: 'queued for staff (handler not yet wired in n8n; Python sibling exists)', sms: $json.sms, classification: $json.classification, _verify: $json._verify } }];

// Stub handler for `general_message`. Per Q9 — patient gets the generic
// clinic ack; staff handles the actual response.
return [{ json: { handled: false, intent: 'general_message', note: 'queued for staff (general)', sms: $json.sms, classification: $json.classification, _verify: $json._verify } }];

// Audit log writer. Per Q7, audit lives in SQLite via audit_log.py — NOT
// n8n's built-in execution log. The cleanest way to call audit_log.py from
// here is to invoke it as a subprocess via the Execute Command node. We use
// a Function node to BUILD the command + args, then hand off to the next
// node. This keeps secrets out of node parameters (the pepper is read from
// AUDIT_LOG_PEPPER env inside the Python subprocess, not interpolated here).
//
// Schema mirrors AuditLog.log(...) in audit_log.py exactly.

const sms = $json.sms || {};
const cls = $json.classification || {};
const handler = $json.handled !== undefined ? $json : { handled: false };
const verify = $json._verify || { ok: true };

const actor = sms.from_number || 'unknown_sms_sender';
const action = verify.ok ? 'SMS_INBOUND' : 'WEBHOOK_REJECT';
const resultSummary = verify.ok
  ? `intent=${cls.intent || 'unknown'} conf=${cls.confidence || '?'} handled=${Boolean(handler.handled)}`
  : `verification_failed`;
const errorMsg = verify.ok ? null : (verify.reason || 'unknown');

const auditPayload = {
  actor,
  intent: 'triage-classify',
  action,
  result_summary: resultSummary,
  patient_id: actor || null,
  error_msg: errorMsg
};

// Pass the original handler output through unchanged for the final Respond node.
return [{
  json: {
    audit: auditPayload,
    audit_cmd: 'python3',
    audit_args: [
      '-c',
      `import json, os, sys; sys.path.insert(0, '/Users/shubh/n8n-office/python'); from integrations.audit_log import AuditLog; a = AuditLog(os.environ.get('AUDIT_LOG_PATH', '/Users/shubh/n8n-office/cache/audit_log.sqlite'), pepper=os.environ['AUDIT_LOG_PEPPER']); p = json.loads(sys.stdin.read()); a.log(**p); print('ok')`
    ],
    audit_stdin: JSON.stringify(auditPayload),
    response: {
      ok: true,
      intent: cls.intent || 'general_message',
      confidence: cls.confidence,
      secondary: cls.secondary || [],
      reason: cls.reason,
      handler: { handled: Boolean(handler.handled), note: handler.note || '' },
      ack_template: "This is Atlantic Pain & Wellness. We received your message and a staff member will follow up. For urgent issues, call our main line. For emergencies, call 911."
    }
  }
}];

// Verification failed branch — still 200 per Q10 so RC doesn't retry-then-
// disable. Build a minimal audit payload (no classification happened) and
// hand to the same audit writer chain.
const payload = $items('Extract SMS fields', 0, 0)[0]?.json || $json;
const sms = payload.sms || { from_number: '' };
const verify = payload._verify || $json._verify || { ok: false, reason: 'unknown' };

const actor = sms.from_number || 'unknown_sms_sender';
const auditPayload = {
  actor,
  intent: 'triage-classify',
  action: 'WEBHOOK_REJECT',
  result_summary: 'verification_failed',
  patient_id: actor || null,
  error_msg: verify.reason || 'unknown'
};

return [{
  json: {
    audit: auditPayload,
    audit_cmd: 'python3',
    audit_args: [
      '-c',
      `import json, os, sys; sys.path.insert(0, '/Users/shubh/n8n-office/python'); from integrations.audit_log import AuditLog; a = AuditLog(os.environ.get('AUDIT_LOG_PATH', '/Users/shubh/n8n-office/cache/audit_log.sqlite'), pepper=os.environ['AUDIT_LOG_PEPPER']); p = json.loads(sys.stdin.read()); a.log(**p); print('ok')`
    ],
    audit_stdin: JSON.stringify(auditPayload),
    response: {
      ok: false,
      stage: 'verification',
      reason: verify.reason || 'verification failed'
    }
  }
}];
